import{_ as e,o as a,c as r,ag as o}from"./chunks/framework.qXLDknWC.js";const m=JSON.parse('{"title":"Import & Export","description":"","frontmatter":{},"headers":[],"relativePath":"features/import-export.md","filePath":"features/import-export.md"}'),l={name:"features/import-export.md"};function i(s,t,n,h,d,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="import-export" tabindex="-1">Import &amp; Export <a class="header-anchor" href="#import-export" aria-label="Permalink to &quot;Import &amp; Export&quot;">​</a></h1><p>CharacterVault plays well with the wider character card ecosystem. Whether you&#39;re moving characters from other apps, sharing them with friends, or just backing up your work, you can import and export in formats that work with SillyTavern, TavernAI, and most other character card tools.</p><h2 id="importing-characters" tabindex="-1">Importing Characters <a class="header-anchor" href="#importing-characters" aria-label="Permalink to &quot;Importing Characters&quot;">​</a></h2><p>Click <strong>Import</strong> in the vault header, then select a file. CharacterVault accepts PNG images with embedded data or JSON files.</p><h3 id="png-files" tabindex="-1">PNG Files <a class="header-anchor" href="#png-files" aria-label="Permalink to &quot;PNG Files&quot;">​</a></h3><p>Character cards saved as PNG images store all their data in a special metadata chunk inside the file. When you import one, CharacterVault reads that chunk, parses the JSON inside, and creates a new character with the image as its avatar. This works with cards from SillyTavern, TavernAI, and similar tools.</p><h3 id="json-files" tabindex="-1">JSON Files <a class="header-anchor" href="#json-files" aria-label="Permalink to &quot;JSON Files&quot;">​</a></h3><p>JSON imports are flexible. CharacterVault recognizes several formats:</p><ul><li><strong>Flat V2</strong> — a simple JSON object with fields like <code>name</code>, <code>description</code>, <code>personality</code> sitting at the top level</li><li><strong>Wrapped V2 or V3</strong> — the same fields nested inside a structure that declares the specification version</li><li><strong>CharacterVault export</strong> — CharacterVault&#39;s own format includes everything the app stores about a character</li></ul><p>All three load cleanly into your vault.</p><h3 id="from-sillytavern" tabindex="-1">From SillyTavern <a class="header-anchor" href="#from-sillytavern" aria-label="Permalink to &quot;From SillyTavern&quot;">​</a></h3><p>The <strong><a href="https://github.com/spaceman2408/SillyTavern-CharacterVaultExport" target="_blank" rel="noreferrer">SillyTavern CharacterVault Export Extension</a></strong> adds an &quot;Export to CharacterVault&quot; button right inside SillyTavern&#39;s export menu. When you use it, the extension copies the character to your clipboard in a format CharacterVault understands — no need to save files manually.</p><h2 id="exporting-characters" tabindex="-1">Exporting Characters <a class="header-anchor" href="#exporting-characters" aria-label="Permalink to &quot;Exporting Characters&quot;">​</a></h2><p>Open a character and click <strong>Export</strong> in the toolbar. You have two choices:</p><h3 id="png" tabindex="-1">PNG <a class="header-anchor" href="#png" aria-label="Permalink to &quot;PNG&quot;">​</a></h3><p>Your character becomes a PNG image with all data embedded in the image file itself. This is the most versatile option — send it to anyone and they can drag it straight into SillyTavern, CharacterVault, or any compatible app. The data is embedded as a V3 specification.</p><h3 id="json" tabindex="-1">JSON <a class="header-anchor" href="#json" aria-label="Permalink to &quot;JSON&quot;">​</a></h3><p>Exports a JSON file using the V3 specification. Includes name, description, personality, scenario, greetings, lorebook, creator information, tags, and notes.</p><h2 id="what-each-format-includes" tabindex="-1">What Each Format Includes <a class="header-anchor" href="#what-each-format-includes" aria-label="Permalink to &quot;What Each Format Includes&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">PNG</th><th style="text-align:left;">JSON</th></tr></thead><tbody><tr><td style="text-align:left;">Basic fields (name, description, etc.)</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">Alternate greetings</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">Lorebook / character book</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">Creator name, version, tags</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">Creator notes</td><td style="text-align:left;">✓</td><td style="text-align:left;">✓</td></tr><tr><td style="text-align:left;">Character image</td><td style="text-align:left;">✓</td><td style="text-align:left;">—</td></tr></tbody></table><h2 id="lorebook-import-export" tabindex="-1">Lorebook Import &amp; Export <a class="header-anchor" href="#lorebook-import-export" aria-label="Permalink to &quot;Lorebook Import &amp; Export&quot;">​</a></h2><p>You can also import and export lorebooks independently within the <strong>Lorebook Editor</strong>. Lorebook export produces a JSON file. This lets you:</p><ul><li>Share world info between characters</li><li>Import standalone lorebook files from SillyTavern</li><li>Back up lorebooks separately from character cards</li></ul><p>See <a href="/CharacterVault/docs/features/lorebook-editor#import--export">Lorebook Editor → Import &amp; Export</a> for details.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/features/vault-organization">Organize your vault</a></li><li><a href="/CharacterVault/docs/features/snapshots-history">Back up with snapshots</a></li></ul>',26)])])}const u=e(l,[["render",i]]);export{m as __pageData,u as default};
